const $=s=>document.querySelector(s);
const days=['Seg','Ter','Qua','Qui','Sex','Sáb','Dom'];
let data,selected,day=(new Date().getDay()+6)%7,limit=30,start=6,end=23;
const normalize=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=s=>new Date(s).toLocaleDateString('pt-BR');
const place=g=>[g.address,g.neighborhood&&!normalize(g.address).includes(normalize(g.neighborhood))?g.neighborhood:'',g.city,g.state].filter(Boolean).join(' · ')||`Localização: ${g.latitude.toFixed(4)}, ${g.longitude.toFixed(4)}`;
function matches(){const terms=normalize($('#search').value).split(/\s+/).filter(Boolean);const city=normalize($('#city').value.trim()),neighborhood=normalize($('#neighborhood').value.trim());return data.gyms.filter(g=>(!$('#state').value||g.state===$('#state').value)&&normalize(g.city).includes(city)&&normalize(g.neighborhood||'').includes(neighborhood)&&benefitMatches(g)&&terms.every(t=>g.search_text.includes(t)));}
function suggestions(){
 const state=$('#state').value,city=normalize($('#city').value.trim());
 const cities=(data.cities||[]).filter(c=>!state||c.state===state);
 $('#cities').replaceChildren(...[...new Set(cities.map(c=>c.name))].sort((a,b)=>a.localeCompare(b,'pt-BR')).map(c=>new Option(c,c)));
 const official=(data.neighborhoods||[]).filter(n=>(!state||n.state===state)&&(!city||normalize(n.city).includes(city))).map(n=>n.name);
 const mapped=data.gyms.filter(g=>(!state||g.state===state)&&(!city||normalize(g.city).includes(city))).map(g=>g.neighborhood).filter(Boolean);
 $('#neighborhoods').replaceChildren(...[...new Set([...official,...mapped])].sort((a,b)=>a.localeCompare(b,'pt-BR')).map(n=>new Option(n,n)));
}

function benefitStatus(g,key){const b=g.benefits?.[key];if(!b)return 'unknown';const age=Date.now()-Date.parse(b.checked_at+'T00:00:00Z');return age>30*86400000?'unknown':b.status;}
function benefitMatches(g){const v=$('#benefit').value;return !v||(v==='both'?['wellhub','totalpass'].every(k=>benefitStatus(g,k)==='yes'):benefitStatus(g,v)==='yes');}
function benefitCards(g){return '<div class="benefit-cards">'+[['wellhub','Wellhub (Gympass)','https://wellhub.com/pt-br/search/'],['totalpass','TotalPass','https://totalpass.com/br/academias/']].map(([key,label,url])=>{const b=g.benefits?.[key];const status=benefitStatus(g,key);return `<div><strong>${label}</strong><span class="${status==='yes'?'confirmed':''}">${{yes:'Aceita · parceria verificada',no:'Não aceita · informação verificada',unknown:'Aceitação não informada'}[status]}</span>${b?`<small>Última verificação: ${date(b.checked_at+'T12:00:00Z')}</small>`:''}<a href="${escape(b?.source_url||url)}" target="_blank" rel="noopener">${b?'Ver fonte da unidade':'Consultar rede parceira'} ↗</a></div>`;}).join('')+'</div><p class="small benefit-note">Confirme a unidade e o plano no aplicativo do benefício. Não informado não significa que a academia não aceita.</p>';}
$('#benefit').addEventListener('change',()=>{if(data)search();});
function renderResults(){const gyms=matches();$('#count').textContent=gyms.length.toLocaleString('pt-BR');$('#results').innerHTML=gyms.slice(0,limit).map(g=>`<button class="gym ${g.id===selected?.id?'selected':''}" data-id="${escape(g.id)}" aria-pressed="${g.id===selected?.id}"><strong>${escape(g.name)}</strong><span>${escape(place(g))}</span><span class="gymtag">Explorar horários ↗</span></button>`).join('')||'<p class="empty">Nenhuma academia cadastrada corresponde a estes filtros. Isso não significa que a cidade ou o bairro não tenha academias. O bairro ou convênio pode não estar informado na base. Limpe esses filtros para ampliar a busca.</p>';$('#more').hidden=gyms.length<=limit;}
function renderDetail(){if(!selected){$('#detail').innerHTML='<p class="empty">Selecione uma academia nos resultados.</p>';return;}const g=selected;const points=data.profiles.filter(p=>p.weekday===day&&p.hour>=start&&p.hour<end);const best=[...points].sort((a,b)=>a.score-b.score||a.hour-b.hour)[0];const worst=[...points].sort((a,b)=>b.score-a.score||a.hour-b.hour)[0];const maps='https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(`${g.name} ${g.address} ${g.city} ${g.state} ${g.latitude},${g.longitude}`);const options=Array.from({length:25},(_,h)=>h);$('#detail').innerHTML=`<div class="detail-top"><div><span class="pill">ESTIMATIVA GENÉRICA · CONFIANÇA BAIXA</span><h2>${escape(g.name)}</h2><p class="small">${escape(place(g))}</p></div><a class="maplink" href="${maps}" target="_blank" rel="noopener">Ver no Google Maps ↗</a></div>${benefitCards(g)}<div class="notice">Este perfil é igual para todas as academias: uma referência histórica do Kaggle, sem medição desta unidade. Confirme os horários de pico e de funcionamento no Google Maps.</div><div class="days" aria-label="Dia da semana">${days.map((d,i)=>`<button data-day="${i}" class="${i===day?'active':''}" aria-pressed="${i===day}">${d}</button>`).join('')}</div><div class="window"><span>Comparar entre</span><select id="start" aria-label="Hora inicial">${options.slice(0,24).map(h=>`<option value="${h}" ${h===start?'selected':''}>${h}h</option>`).join('')}</select><span>e</span><select id="end" aria-label="Hora final">${options.slice(1).map(h=>`<option value="${h}" ${h===end?'selected':''}>${h}h</option>`).join('')}</select><span>· Não indica horário de funcionamento</span></div><div class="summary"><div class="stat"><span>↘ MENOR MOVIMENTO ESTIMADO</span><strong>${best?`${best.hour}h – ${best.hour+1}h`:'Sem dados'}</strong><small>Dentro do período selecionado</small></div><div class="stat busy"><span>↗ MAIOR MOVIMENTO ESTIMADO</span><strong>${worst?`${worst.hour}h – ${worst.hour+1}h`:'Sem dados'}</strong><small>Dentro do período selecionado</small></div></div><div class="chart-head"><h3>Movimento ao longo do dia</h3><span>Índice relativo · 0 a 100</span></div><div class="chart" aria-label="Gráfico de tendência horária">${points.map(p=>`<button class="bar ${p.score<35?'low':p.score>=70?'high':''}" style="--height:${Math.max(2,p.score)}%" data-hour="${p.hour}" aria-label="${p.hour} horas, índice estimado ${p.score} de 100" title="${p.hour}h: índice ${p.score}/100"><i></i><span>${p.hour}h</span></button>`).join('')}</div><div class="legend"><span>Mais tranquilo</span><span>Moderado</span><span>Mais movimento</span></div><p id="chartnote" class="chart-note">Toque em uma barra para ver a estimativa. O índice não é percentual de ocupação.</p><p class="small">Funcionamento informado no cadastro: ${escape(g.opening_hours||'não disponível')}. Verifique com a academia.</p>`;}
function search(){limit=30;const gyms=matches();if(!gyms.some(g=>g.id===selected?.id))selected=gyms[0];renderResults();renderDetail();}
$('#searchform').addEventListener('submit',e=>{e.preventDefault();if(data)search();});$('#search').addEventListener('input',()=>{if(data)search();});$('#state').addEventListener('change',()=>{if(data){$('#city').value='';$('#neighborhood').value='';suggestions();search();}});$('#city').addEventListener('input',()=>{if(data){$('#neighborhood').value='';suggestions();search();}});$('#neighborhood').addEventListener('input',()=>{if(data)search();});$('#more').addEventListener('click',()=>{limit+=30;renderResults();});
$('#results').addEventListener('click',e=>{const b=e.target.closest('[data-id]');if(!b)return;selected=data.gyms.find(g=>g.id===b.dataset.id);renderResults();renderDetail();});
$('#detail').addEventListener('click',e=>{const b=e.target.closest('[data-day]');if(b){day=Number(b.dataset.day);renderDetail();}const bar=e.target.closest('[data-hour]');if(bar){const p=data.profiles.find(p=>p.weekday===day&&p.hour===Number(bar.dataset.hour));$('#chartnote').textContent=`${p.hour}h–${p.hour+1}h: índice estimado ${p.score}/100, baseado em ${p.samples} registros históricos da academia de referência.`;}});
$('#detail').addEventListener('change',e=>{if(e.target.id==='start'){start=Number(e.target.value);if(start>=end)end=start+1;}else if(e.target.id==='end'){end=Number(e.target.value);if(end<=start)start=end-1;}renderDetail();});
async function init(){try{const r=await fetch('data.json');if(!r.ok)throw Error();data=await r.json();if(!data.gyms.length)throw Error();data.gyms.sort((a,b)=>a.name.localeCompare(b.name,'pt-BR'));const states=[...new Set(data.cities.map(g=>g.state).filter(Boolean))].sort();states.forEach(s=>$('#state').add(new Option(s,s)));suggestions();selected=data.gyms.find(g=>normalize(g.city).includes('belo horizonte'))||data.gyms[0];$('#freshness').textContent=`Cadastro consultado em ${date(data.meta.catalog_updated_at)} · ${data.gyms.length.toLocaleString('pt-BR')} academias`;if(Date.now()-Date.parse(data.meta.catalog_updated_at)>172800000)$('#freshness').textContent+=' · Base sem atualização há mais de 48h';$('#method').textContent=data.meta.methodology;$('#sourceperiod').textContent=`Registros do modelo: ${data.meta.observation_start} a ${data.meta.observation_end}. Fonte consultada em ${date(data.meta.model_checked_at)}. Nova consulta não significa novos registros na fonte.`;renderResults();renderDetail();if(document.modelContext?.registerTool){Promise.resolve(document.modelContext.registerTool({name:'search_gyms',description:'Pesquisar academias e atualizar os resultados visíveis.',inputSchema:{type:'object',properties:{query:{type:'string'}},required:['query'],additionalProperties:false},execute(input){if(typeof input.query!=='string'||input.query.length>200)throw Error('Consulta inválida');$('#search').value=input.query;search();return {count:matches().length,gyms:matches().slice(0,10).map(g=>({id:g.id,name:g.name,city:g.city}))};}})).catch(()=>{});}}catch(e){$('#freshness').textContent='Base indisponível';$('#results').innerHTML='<p class="empty">Não foi possível carregar a base. <button onclick="location.reload()">Tentar novamente</button></p>';$('#detail').innerHTML='<p class="empty">Os dados estarão disponíveis assim que a conexão for restabelecida.</p>';}}
init();
